    51	function recentMessages(messages: ChatMessage[]) {
    52	  const window = messages
    53	    .filter((message) => message.content.trim().length > 0)
    54	    .slice(-MAX_HISTORY_MESSAGES);
    55	
    56	  // Anthropic requires the first conversation message to be a user turn, and
    57	  // Gemini has the same practical alternation expectation for contents. When a
    58	  // long transcript ending in the newest user prompt is sliced to an even-sized
    59	  // window, the first retained turn can be the prior assistant response. Drop
    60	  // any leading assistant-only context so every provider receives a valid
    61	  // user-started transcript.
    62	  while (window[0]?.role === "assistant") window.shift();
    63	  return window;
    64	}
