   185	function providerErrorMessage(payload: unknown, fallback: string): string {
   186	  if (typeof payload !== "object" || payload === null) return fallback;
   187	  const record = payload as Record<string, unknown>;
   188	  const error = record.error;
   189	  if (typeof error === "string" && error.trim()) return error;
   190	  if (typeof error === "object" && error !== null) {
   191	    const message = (error as Record<string, unknown>).message;
   192	    if (typeof message === "string" && message.trim()) return message;
   193	  }
   194	  const message = record.message;
   195	  return typeof message === "string" && message.trim() ? message : fallback;
   196	}
   197	
   198	function extractProviderText(settings: ProviderSettings, payload: unknown): string {
   199	  const record = payload as Record<string, any>;
   200	  if (settings.provider === "openai") {
   201	    if (typeof record.output_text === "string" && record.output_text.trim()) return record.output_text.trim();
   202	    const text = Array.isArray(record.output)
   203	      ? record.output
   204	        .flatMap((item: any) => Array.isArray(item?.content) ? item.content : [])
   205	        .filter((part: any) => part?.type === "output_text" && typeof part?.text === "string")
   206	        .map((part: any) => part.text)
   207	        .join("\n")
   208	      : "";
   209	    if (text.trim()) return text.trim();
   210	  } else if (settings.provider === "anthropic") {
   211	    const text = Array.isArray(record.content)
   212	      ? record.content.filter((block: any) => block?.type === "text").map((block: any) => block.text).join("\n")
   213	      : "";
   214	    if (text.trim()) return text.trim();
   215	  } else if (settings.provider === "google") {
   216	    const text = record.candidates?.[0]?.content?.parts
   217	      ?.filter((part: any) => part?.thought !== true)
   218	      .map((part: any) => typeof part?.text === "string" ? part.text : "")
   219	      .join("\n");
   220	    if (typeof text === "string" && text.trim()) return text.trim();
   221	  } else {
   222	    const content = record.choices?.[0]?.message?.content;
   223	    if (typeof content === "string" && content.trim()) return content.trim();
   224	    if (Array.isArray(content)) {
   225	      const text = content.map((part: any) => part?.text ?? "").join("\n");
   226	      if (text.trim()) return text.trim();
   227	    }
   228	  }
   229	  throw new Error("The provider returned a response without readable text.");
   230	}
