   232	const EVENT_SEPARATOR = /\r?\n\r?\n/;
   233	
   234	/**
   235	 * Splits an incoming SSE text stream into `data:` payload strings, carrying any
   236	 * partial trailing event across chunk boundaries.
   237	 */
   238	export function createSseParser(): (chunk: string) => string[] {
   239	  let buffer = "";
   240	  return (chunk: string) => {
   241	    buffer += chunk;
   242	    const events: string[] = [];
   243	    for (let match = EVENT_SEPARATOR.exec(buffer); match; match = EVENT_SEPARATOR.exec(buffer)) {
   244	      const rawEvent = buffer.slice(0, match.index);
   245	      buffer = buffer.slice(match.index + match[0].length);
   246	      const data = rawEvent
   247	        .split(/\r?\n/)
   248	        .filter((line) => line.startsWith("data:"))
   249	        .map((line) => line.slice(5).trim())
   250	        .join("\n");
   251	      if (data) events.push(data);
   252	    }
   253	    return events;
   254	  };
   255	}
   256	
   257	function textFromParts(parts: unknown): string {
   258	  if (typeof parts === "string") return parts;
   259	  if (!Array.isArray(parts)) return "";
   260	  // Gemini returns its thinking as ordinary parts flagged `thought: true`.
   261	  // Those belong to the reasoning budget, not the reply the learner reads.
   262	  return parts
   263	    .filter((part: any) => part?.thought !== true)
   264	    .map((part: any) => (typeof part?.text === "string" ? part.text : ""))
   265	    .join("");
   266	}
