   268	/**
   269	 * Pulls the incremental text out of one SSE event for the given provider.
   270	 * Returns an empty string for keep-alives and non-text events.
   271	 */
   272	export function extractStreamDelta(settings: ProviderSettings, data: string): string {
   273	  if (!data || data === "[DONE]") return "";
   274	  let payload: any;
   275	  try {
   276	    payload = JSON.parse(data);
   277	  } catch {
   278	    return "";
   279	  }
   280	
   281	  if (payload?.error) {
   282	    throw new Error(providerErrorMessage(payload, "The provider reported a streaming error."));
   283	  }
   284	
   285	  if (settings.provider === "anthropic") {
   286	    if (payload.type === "content_block_delta" && payload.delta?.type === "text_delta") {
   287	      return typeof payload.delta.text === "string" ? payload.delta.text : "";
   288	    }
   289	    return "";
   290	  }
   291	
   292	  if (settings.provider === "openai") {
   293	    return payload.type === "response.output_text.delta" && typeof payload.delta === "string" ? payload.delta : "";
   294	  }
   295	
   296	  if (settings.provider === "google") {
   297	    return textFromParts(payload?.candidates?.[0]?.content?.parts);
   298	  }
   299	
   300	  const delta = payload?.choices?.[0]?.delta;
   301	  if (typeof delta?.content === "string") return delta.content;
   302	  return textFromParts(delta?.content);
   303	}
