   305	async function throwProviderError(response: Response): Promise<never> {
   306	  const text = await response.text().catch(() => "");
   307	  let payload: unknown = {};
   308	  try {
   309	    payload = text ? JSON.parse(text) : {};
   310	  } catch {
   311	    payload = {};
   312	  }
   313	  throw new Error(providerErrorMessage(payload, `Provider request failed with HTTP ${response.status}.`));
   314	}
   315	
   316	export interface StreamCompletionOptions extends ProviderRequestOptions {
   317	  /** Called with each incremental text chunk as it arrives. */
   318	  onDelta?: (delta: string, accumulated: string) => void;
   319	  fetchImpl?: FetchLike;
   320	}
   321	
   322	/**
   323	 * Streams a completion, invoking `onDelta` per chunk and resolving with the
   324	 * full text. Falls back to a single non-streamed read when the provider
   325	 * responds without a readable body.
   326	 */
   327	export async function streamCompletion(
   328	  settings: ProviderSettings,
   329	  apiKey: string | null,
   330	  messages: ChatMessage[],
   331	  options: StreamCompletionOptions = {},
   332	): Promise<string> {
   333	  const { onDelta, fetchImpl = fetch, ...requestOptions } = options;
   334	  const request = buildProviderRequest(settings, apiKey, messages, { ...requestOptions, stream: true });
   335	  const response = await fetchImpl(request.url, request.init);
   336	
   337	  if (!response.ok) await throwProviderError(response);
   338	
   339	  const body = response.body;
   340	  if (!body) {
   341	    // No readable stream on this platform — take the whole payload at once.
   342	    return wholePayloadFallback(settings, await response.text(), onDelta);
   343	  }
   344	
   345	  const decoder = new TextDecoder();
   346	  const parse = createSseParser();
   347	  const reader = body.getReader();
   348	  let accumulated = "";
   349	  let raw = "";
   350	
   351	  try {
   352	    while (true) {
   353	      const { done, value } = await reader.read();
   354	      if (done) break;
   355	      const chunk = decoder.decode(value, { stream: true });
   356	      raw += chunk;
   357	      for (const data of parse(chunk)) {
   358	        const delta = extractStreamDelta(settings, data);
   359	        if (!delta) continue;
   360	        accumulated += delta;
   361	        onDelta?.(delta, accumulated);
   362	      }
   363	    }
   364	  } finally {
   365	    reader.releaseLock();
   366	  }
   367	
   368	  const trimmed = accumulated.trim();
   369	  if (trimmed) return trimmed;
   370	
   371	  // Some OpenAI-compatible servers (local runtimes especially) ignore
   372	  // `stream: true` and answer with one plain JSON body instead of SSE.
   373	  return wholePayloadFallback(settings, raw, onDelta);
   374	}
   375	
   376	function wholePayloadFallback(
   377	  settings: ProviderSettings,
   378	  text: string,
   379	  onDelta?: (delta: string, accumulated: string) => void,
   380	): string {
   381	  let payload: unknown;
   382	  try {
   383	    payload = text.trim() ? JSON.parse(text) : {};
   384	  } catch {
   385	    throw new Error("The provider returned a response without readable text.");
   386	  }
   387	  const content = extractProviderText(settings, payload);
   388	  onDelta?.(content, content);
   389	  return content;
   390	}
   391	
   392	export async function requestCompletion(
   393	  settings: ProviderSettings,
   394	  apiKey: string | null,
   395	  messages: ChatMessage[],
   396	  signal?: AbortSignal,
   397	  fetchImpl: FetchLike = fetch,
   398	  systemPrompt?: string,
   399	): Promise<string> {
   400	  const request = buildProviderRequest(settings, apiKey, messages, { signal, systemPrompt });
   401	  const response = await fetchImpl(request.url, request.init);
   402	  const responseText = await response.text();
   403	  let payload: unknown = {};
   404	  try {
   405	    payload = responseText ? JSON.parse(responseText) : {};
   406	  } catch {
   407	    if (!response.ok) throw new Error(`Provider request failed with HTTP ${response.status}.`);
   408	    throw new Error("The provider returned an invalid JSON response.");
   409	  }
   410	
   411	  if (!response.ok) {
   412	    throw new Error(providerErrorMessage(payload, `Provider request failed with HTTP ${response.status}.`));
   413	  }
   414	  return extractProviderText(settings, payload);
   415	}

