     1	import { createContext, type PropsWithChildren, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
     2	import { loadUiSettings, saveUiSettings } from "@/lib/ui-settings-storage";
     3	import { DEFAULT_UI_SETTINGS, type KeatingUiSettings } from "@/lib/ui-settings";
     4	
     5	interface UiSettingsContextValue {
     6	  settings: KeatingUiSettings;
     7	  /** True once the stored preferences have replaced the defaults. */
     8	  loaded: boolean;
     9	  updateSettings: (patch: Partial<KeatingUiSettings>) => void;
    10	}
    11	
    12	const UiSettingsContext = createContext<UiSettingsContextValue | null>(null);
    13	
    14	/**
    15	 * Sits above the theme provider so the stored appearance is known before any
    16	 * screen paints, and above the session provider so both can read it.
    17	 */
    18	export function UiSettingsProvider({ children }: PropsWithChildren) {
    19	  const [settings, setSettings] = useState<KeatingUiSettings>(DEFAULT_UI_SETTINGS);
    20	  const [loaded, setLoaded] = useState(false);
    21	  const loadedRef = useRef(false);
    22	
    23	  useEffect(() => {
    24	    let cancelled = false;
    25	    loadUiSettings()
    26	      .then((stored) => {
    27	        if (cancelled) return;
    28	        setSettings(stored);
    29	      })
    30	      .finally(() => {
    31	        if (cancelled) return;
    32	        loadedRef.current = true;
    33	        setLoaded(true);
    34	      });
    35	    return () => {
    36	      cancelled = true;
    37	    };
    38	  }, []);
    39	
    40	  const updateSettings = useCallback((patch: Partial<KeatingUiSettings>) => {
    41	    setSettings((current) => {
    42	      const next = { ...current, ...patch };
    43	      // Writing before the initial read lands would persist the defaults over
    44	      // whatever the learner had already chosen.
    45	      if (loadedRef.current) {
    46	        saveUiSettings(next).catch((error) => console.warn("Failed to save UI settings:", error));
    47	      }
    48	      return next;
    49	    });
    50	  }, []);
    51	
    52	  const value = useMemo(() => ({ settings, loaded, updateSettings }), [settings, loaded, updateSettings]);
    53	  return <UiSettingsContext.Provider value={value}>{children}</UiSettingsContext.Provider>;
    54	}
    55	
    56	export function useUiSettings(): UiSettingsContextValue {
    57	  const context = useContext(UiSettingsContext);
    58	  if (!context) throw new Error("useUiSettings must be used inside UiSettingsProvider.");
    59	  return context;
    60	}

### mobile/src/lib/ui-settings.ts
     1	/**
     2	 * Device-local UI preferences, mirroring the web app's `keating_ui_settings`
     3	 * store. Kept free of React Native imports so the normalizer stays unit
     4	 * testable under `bun test`.
     5	 */
     6	
     7	/** Follows the OS unless the learner pins a scheme. */
     8	export type ThemePreference = "system" | "light" | "dark";
     9	
    10	/**
    11	 * `system` keeps the platform UI face for prose and Space Mono for the
    12	 * terminal-style accents, which is how the app looked before the setting
    13	 * existed. The named options restyle the whole app the way the web build does.
    14	 */
    15	export type UiFontFamily = "system" | "space-mono" | "jetbrains-mono" | "roboto";
    16	
    17	/** Same ladder the web app exposes, mapped per provider at request time. */
    18	export type ReasoningLevel = "off" | "minimal" | "low" | "medium" | "high" | "xhigh";
    19	
    20	export interface KeatingUiSettings {
    21	  theme: ThemePreference;
    22	  fontFamily: UiFontFamily;
    23	  /** Render interactive quiz/question/goal cards instead of the raw tag text. */
    24	  showToolUi: boolean;
    25	  /** Show the provider's own error text rather than a short summary. */
    26	  showRawErrors: boolean;
    27	  reasoningLevel: ReasoningLevel;
    28	}
    29	
    30	export const DEFAULT_UI_SETTINGS: KeatingUiSettings = {
    31	  theme: "system",
    32	  fontFamily: "system",
    33	  showToolUi: true,
    34	  showRawErrors: false,
    35	  reasoningLevel: "medium",
    36	};
    37	
    38	export const THEME_OPTIONS: ReadonlyArray<{ value: ThemePreference; label: string }> = [
    39	  { value: "system", label: "System" },
    40	  { value: "light", label: "Light" },
    41	  { value: "dark", label: "Dark" },
    42	];
    43	
    44	export const FONT_FAMILY_OPTIONS: ReadonlyArray<{
    45	  value: UiFontFamily;
    46	  label: string;
    47	  description: string;
    48	}> = [
    49	  { value: "system", label: "System", description: "The platform UI face, with Space Mono for accents." },
    50	  { value: "space-mono", label: "Space Mono", description: "Retro monospace across the whole app." },
    51	  { value: "jetbrains-mono", label: "JetBrains Mono", description: "Terminal monospace matching the Keating brand." },
    52	  { value: "roboto", label: "Roboto", description: "Clean sans serif for prose." },
    53	];
    54	
    55	export const REASONING_LEVEL_OPTIONS: ReadonlyArray<{
    56	  value: ReasoningLevel;
    57	  label: string;
    58	  description: string;
    59	}> = [
    60	  { value: "off", label: "Off", description: "Answer without a thinking budget." },
    61	  { value: "minimal", label: "Minimal", description: "The smallest budget the model accepts." },
    62	  { value: "low", label: "Low", description: "Quick reasoning for routine questions." },
    63	  { value: "medium", label: "Medium", description: "Balanced depth and latency." },
    64	  { value: "high", label: "High", description: "Longer deliberation on hard problems." },
    65	  { value: "xhigh", label: "Max", description: "The largest budget the provider allows." },
    66	];
    67	
    68	const THEME_VALUES = new Set<ThemePreference>(["system", "light", "dark"]);
    69	const FONT_VALUES = new Set<UiFontFamily>(["system", "space-mono", "jetbrains-mono", "roboto"]);
    70	const REASONING_VALUES = new Set<ReasoningLevel>(["off", "minimal", "low", "medium", "high", "xhigh"]);
    71	
    72	export function normalizeUiSettings(value: unknown): KeatingUiSettings {
    73	  const record = (typeof value === "object" && value !== null ? value : {}) as Partial<KeatingUiSettings>;
    74	  return {
    75	    theme: THEME_VALUES.has(record.theme as ThemePreference) ? record.theme as ThemePreference : DEFAULT_UI_SETTINGS.theme,
    76	    fontFamily: FONT_VALUES.has(record.fontFamily as UiFontFamily)
    77	      ? record.fontFamily as UiFontFamily
    78	      : DEFAULT_UI_SETTINGS.fontFamily,
    79	    showToolUi: typeof record.showToolUi === "boolean" ? record.showToolUi : DEFAULT_UI_SETTINGS.showToolUi,
    80	    showRawErrors: typeof record.showRawErrors === "boolean" ? record.showRawErrors : DEFAULT_UI_SETTINGS.showRawErrors,
    81	    reasoningLevel: REASONING_VALUES.has(record.reasoningLevel as ReasoningLevel)
    82	      ? record.reasoningLevel as ReasoningLevel
    83	      : DEFAULT_UI_SETTINGS.reasoningLevel,
    84	  };
    85	}
    86	
    87	/**
    88	 * Resolves the preference against the OS scheme. `null`/`undefined` from
    89	 * `useColorScheme()` means the platform could not report one, which stays dark
    90	 * because that is the app's designed default.
    91	 */
    92	export function resolveThemeName(
    93	  preference: ThemePreference,
    94	  systemScheme: string | null | undefined,
    95	): "light" | "dark" {
    96	  if (preference === "light" || preference === "dark") return preference;
    97	  return systemScheme === "light" ? "light" : "dark";
    98	}

