     1	/**
     2	 * Maps the shared reasoning ladder onto each provider's own thinking control.
     3	 * Pure so `bun test` can pin the mapping without a React Native runtime.
     4	 */
     5	import type { ReasoningLevel } from "./ui-settings";
     6	
     7	/** Effort names the OpenAI Responses API and its compatible gateways accept. */
     8	export type OpenAiEffort = "minimal" | "low" | "medium" | "high";
     9	
    10	/** `xhigh` has no OpenAI equivalent, so it saturates at `high`. */
    11	export function openAiReasoningEffort(level: ReasoningLevel): OpenAiEffort | null {
    12	  switch (level) {
    13	    case "off":
    14	      return null;
    15	    case "minimal":
    16	      return "minimal";
    17	    case "low":
    18	      return "low";
    19	    case "medium":
    20	      return "medium";
    21	    default:
    22	      return "high";
    23	  }
    24	}
    25	
    26	/**
    27	 * Anthropic bills thinking as a token budget and rejects anything under 1024,
    28	 * so `minimal` and `low` both land on the floor.
    29	 */
    30	export function anthropicThinkingBudget(level: ReasoningLevel): number | null {
    31	  switch (level) {
    32	    case "off":
    33	      return null;
    34	    case "minimal":
    35	    case "low":
    36	      return 1024;
    37	    case "medium":
    38	      return 4096;
    39	    case "high":
    40	      return 8192;
    41	    default:
    42	      return 16384;
    43	  }
    44	}
    45	
    46	/** Gemini takes a thinking budget in tokens; 0 disables it entirely. */
    47	export function googleThinkingBudget(level: ReasoningLevel): number | null {
    48	  switch (level) {
    49	    case "off":
    50	      return null;
    51	    case "minimal":
    52	      return 512;
    53	    case "low":
    54	      return 1024;
    55	    case "medium":
    56	      return 4096;
    57	    case "high":
    58	      return 8192;
    59	    default:
    60	      return 16384;
    61	  }
    62	}
    63	
    64	/**
    65	 * Anthropic requires room for the visible reply on top of the thinking budget,
    66	 * and rejects a `max_tokens` that does not exceed it.
    67	 */
    68	export function anthropicMaxTokens(thinkingBudget: number | null, replyBudget = 4096): number {
    69	  return thinkingBudget === null ? replyBudget : thinkingBudget + replyBudget;
    70	}

