    12	/**
    13	 * Renders an assistant turn: prose as markdown, and any `<keating-… />` tags it
    14	 * carries as interactive cards.
    15	 *
    16	 * While a reply is still streaming the tag is usually incomplete, so parsing
    17	 * simply finds no card yet and the partial markup stays hidden until the
    18	 * closing `/>` arrives.
    19	 */
    20	export function MessageContent({
    21	  messageId,
    22	  content,
    23	  streaming = false,
    24	  onCardResult,
    25	}: {
    26	  messageId: string;
    27	  content: string;
    28	  streaming?: boolean;
    29	  /** Sends a learner turn built from a card back into the conversation. */
    30	  onCardResult: (text: string) => void;
    31	}) {
    32	  const segments = useMemo(() => parseInteractiveSegments(content), [content]);
    33	  const { settings } = useUiSettings();
    34	
    35	  return (
    36	    <View>
    37	      {segments.map((segment, index) => {
    38	        const key = cardKey(messageId, index);
    39	        if (segment.type === "text") {
    40	          return <MarkdownText key={key} content={hideUnclosedTag(segment.content, streaming)} />;
    41	        }
    42	        // Cards stay inert until the reply is complete; submitting mid-stream
    43	        // would interleave a learner turn with the one still arriving.
    44	        if (streaming) return <Fragment key={key} />;
    45	        // With card rendering off the learner still needs to know the tutor
    46	        // produced one, so the tag collapses to an inert label rather than
    47	        // vanishing or dumping its JSON.
    48	        if (!settings.showToolUi) return <CardPlaceholder key={key} segment={segment} />;
    49	        if (segment.type === "quiz") {
    50	          return <QuizCard key={key} cardKey={key} quiz={segment.quiz} onSubmit={onCardResult} />;
    51	        }
    52	        if (segment.type === "question") {
    53	          return <QuestionCard key={key} cardKey={key} form={segment.form} onSubmit={onCardResult} />;
    54	        }
    55	        return <GoalCard key={key} cardKey={key} goal={segment.goal} onReport={onCardResult} />;
    56	      })}
    57	    </View>
    58	  );
