    67	      ? `Question card${segment.form.topic ? ` · ${segment.form.topic}` : ""}`
    68	      : `Learning goal · ${segment.goal.title}`;
    69	  return (
    70	    <View
    71	      style={{
    72	        marginTop: spacing.md,
    73	        paddingHorizontal: spacing.md,
    74	        paddingVertical: spacing.sm,
    75	        borderRadius: radii.md,
    76	        borderWidth: 1,
    77	        borderColor: colors.border,
    78	        backgroundColor: colors.surface,
    79	      }}
