    89	/** Trims a tag that is still being streamed so raw JSON never flashes on screen. */
    90	function hideUnclosedTag(content: string, streaming: boolean): string {
    91	  if (!streaming) return content;
    92	  const opening = content.lastIndexOf("<keating-");
    93	  return opening === -1 ? content : content.slice(0, opening).trimEnd();
