     1	import AsyncStorage from "@react-native-async-storage/async-storage";
     2	import {
     3	  type CatalogModel,
     4	  isCatalogModel,
     5	  MODELS_DEV_CATALOG_URL,
     6	  parseModelsDevCatalog,
     7	} from "./model-catalog";
     8	
     9	const CATALOG_CACHE_KEY = "keating.mobile.model-catalog.v1";
    10	const RECENT_MODELS_KEY = "keating.mobile.recent-models.v1";
    11	const MAX_RECENT_MODELS = 7;
    12	
    13	interface CachedCatalog {
    14	  updatedAt: number;
    15	  models: CatalogModel[];
    16	}
    17	
    18	interface RecentModel {
    19	  key: string;
    20	  timestamp: number;
    21	}
    22	
    23	export async function readCachedModelCatalog(): Promise<CatalogModel[]> {
    24	  const raw = await AsyncStorage.getItem(CATALOG_CACHE_KEY);
    25	  if (!raw) return [];
    26	  try {
    27	    const cached = JSON.parse(raw) as Partial<CachedCatalog>;
    28	    return Array.isArray(cached.models) ? cached.models.filter(isCatalogModel) : [];
    29	  } catch {
    30	    return [];
    31	  }
    32	}
    33	
    34	export async function refreshModelsDevCatalog(
    35	  fetchImpl: typeof fetch = fetch,
    36	  options: { signal?: AbortSignal; timeoutMs?: number } = {},
    37	): Promise<CatalogModel[]> {
    38	  const controller = new AbortController();
    39	  const timeoutMs = options.timeoutMs ?? 30_000;
    40	  const abortFromCaller = () => controller.abort();
    41	  options.signal?.addEventListener("abort", abortFromCaller, { once: true });
    42	  const timeout = setTimeout(() => controller.abort(), timeoutMs);
    43	  try {
    44	    const response = await fetchImpl(MODELS_DEV_CATALOG_URL, {
    45	      headers: { Accept: "application/json" },
    46	      signal: controller.signal,
    47	    });
    48	    if (!response.ok) throw new Error(`models.dev refresh failed (HTTP ${response.status}).`);
    49	    const models = parseModelsDevCatalog(await response.json());
    50	    const cache: CachedCatalog = { updatedAt: Date.now(), models };
    51	    await AsyncStorage.setItem(CATALOG_CACHE_KEY, JSON.stringify(cache));
    52	    return models;
    53	  } catch (error) {
    54	    if (controller.signal.aborted && !options.signal?.aborted) {
    55	      throw new Error("models.dev refresh timed out. Check the connection and retry.");
    56	    }
    57	    throw error;
    58	  } finally {
    59	    clearTimeout(timeout);
    60	    options.signal?.removeEventListener("abort", abortFromCaller);
    61	  }
    62	}
    63	
    64	export async function getRecentModelKeys(): Promise<string[]> {
    65	  const raw = await AsyncStorage.getItem(RECENT_MODELS_KEY);
    66	  if (!raw) return [];
    67	  try {
    68	    const parsed = JSON.parse(raw) as unknown;
    69	    if (!Array.isArray(parsed)) return [];
    70	    return parsed
    71	      .filter((entry): entry is RecentModel => (
    72	        typeof entry === "object" && entry !== null
    73	        && typeof (entry as RecentModel).key === "string"
    74	        && typeof (entry as RecentModel).timestamp === "number"
    75	      ))
    76	      .sort((left, right) => right.timestamp - left.timestamp)
    77	      .slice(0, MAX_RECENT_MODELS)
    78	      .map((entry) => entry.key);
    79	  } catch {
    80	    return [];
    81	  }
    82	}
    83	
    84	export async function addRecentModelKey(key: string): Promise<void> {
    85	  const existing = await getRecentModelKeys();
    86	  const next: RecentModel[] = [key, ...existing.filter((entry) => entry !== key)]
    87	    .slice(0, MAX_RECENT_MODELS)
    88	    .map((entry, index) => ({ key: entry, timestamp: Date.now() - index }));
    89	  await AsyncStorage.setItem(RECENT_MODELS_KEY, JSON.stringify(next));
    90	}

