   108	export function parseModelsDevCatalog(payload: unknown): CatalogModel[] {
   109	  if (!isRecord(payload)) throw new Error("models.dev returned an invalid catalog.");
   110	  const models: CatalogModel[] = [];
   111	
   112	  for (const [providerKey, providerValue] of Object.entries(payload)) {
   113	    if (!MODELS_DEV_PROVIDERS.has(providerKey as ModelsDevProviderId) || !isRecord(providerValue)) continue;
   114	    const provider = providerKey as ModelsDevProviderId;
   115	    const providerLabel = typeof providerValue.name === "string"
   116	      ? providerValue.name
   117	      : providerDefinition(provider).label;
   118	    if (!isRecord(providerValue.models)) continue;
   119	
   120	    for (const [recordKey, modelValue] of Object.entries(providerValue.models)) {
   121	      if (!isRecord(modelValue)) continue;
   122	      const id = typeof modelValue.id === "string" && modelValue.id.trim() ? modelValue.id.trim() : recordKey.trim();
   123	      if (!id) continue;
   124	      const modalities = isRecord(modelValue.modalities) ? modelValue.modalities : {};
   125	      const inputs = stringArray(modalities.input);
   126	      const outputs = stringArray(modalities.output);
   127	      const limits = isRecord(modelValue.limit) ? modelValue.limit : {};
   128	      const contextWindow = finiteNonNegative(limits.context);
   129	
   130	      // Image, speech, embedding, and other non-chat entries share the public
   131	      // catalog. The mobile Tutor can only use models that produce text.
   132	      if (!outputs.includes("text") || contextWindow <= 0 || !isNativeTransportCompatible(provider, id)) continue;
   133	
   134	      models.push({
   135	        key: catalogKey(provider, id),
   136	        provider,
   137	        providerLabel,
   138	        id,
   139	        name: typeof modelValue.name === "string" && modelValue.name.trim() ? modelValue.name.trim() : id,
   140	        description: typeof modelValue.description === "string" ? modelValue.description.trim() : "",
   141	        reasoning: modelValue.reasoning === true,
   142	        vision: inputs.includes("image"),
   143	        contextWindow,
   144	        maxOutputTokens: finiteNonNegative(limits.output),
   145	        transport: NATIVE_PROVIDER_TRANSPORT[provider],
   146	        source: "models.dev",
   147	      });
   148	    }
   149	  }
   150	
   151	  if (models.length === 0) throw new Error("models.dev returned no compatible chat models.");
   152	  return dedupeModels(models).sort(compareModels);
