 1	import { keatingDesignContract, type DesignThemeName } from "@keating/design-contract";
 2	
 3	export type NativeThemeName = DesignThemeName;
 4	
 5	export interface NativeTheme {
 6	  readonly name: NativeThemeName;
 7	  readonly colors: {
 8	    readonly background: string;
 9	    readonly backgroundDeep: string;
10	    readonly surface: string;
11	    readonly surfaceRaised: string;
12	    readonly surfacePressed: string;
13	    readonly text: string;
14	    readonly textMuted: string;
15	    readonly textFaint: string;
16	    readonly primary: string;
17	    readonly primaryStrong: string;
18	    readonly primaryInk: string;
19	    /**
20	     * Accent used as *text or icon on a surface*. The contract only validates
21	     * `accent` as a background, so light mode needs the darker `accentText`
22	     * role to clear 4.5:1. Identical to `primary` in dark mode.
23	     */
24	    readonly primaryText: string;
25	    readonly border: string;
26	    readonly borderStrong: string;
27	    readonly error: string;
28	    readonly errorSurface: string;
29	    readonly warning: string;
30	    readonly success: string;
31	    readonly info: string;
32	    readonly userBubble: string;
33	    readonly overlay: string;
34	  };
35	  readonly statusBarStyle: "light" | "dark";
36	}
37	
38	function mixHex(background: string, foreground: string, foregroundWeight: number): string {
39	  const channels = (value: string) => [1, 3, 5].map((offset) => Number.parseInt(value.slice(offset, offset + 2), 16));
40	  const base = channels(background);
41	  const overlay = channels(foreground);
42	  return `#${base.map((channel, index) => Math.round(channel * (1 - foregroundWeight) + overlay[index]! * foregroundWeight)
43	    .toString(16)
44	    .padStart(2, "0")).join("")}`;
45	}
46	
47	/** Native state roles projected from the browser- and terminal-neutral contract. */
48	export function projectNativeTheme(name: NativeThemeName): NativeTheme {
49	  const colors = keatingDesignContract.themes[name].colors;
50	  const selectedSurface = mixHex(colors.surfaceRaised, colors.accent, name === "dark" ? 0.12 : 0.08);
51	  const pressedSurface = mixHex(colors.surfaceRaised, colors.accent, name === "dark" ? 0.22 : 0.15);
52	  const dangerSurface = mixHex(colors.surfaceMuted, colors.danger, name === "dark" ? 0.18 : 0.1);
53	  return {
54	    name,
55	    colors: {
56	      background: colors.surface,
57	      backgroundDeep: colors.surfaceMuted,
58	      surface: colors.surfaceRaised,
59	      surfaceRaised: selectedSurface,
60	      surfacePressed: pressedSurface,
61	      text: colors.text,
62	      textMuted: colors.mutedText,
63	      textFaint: colors.mutedText,
64	      primary: colors.accent,
65	      primaryStrong: colors.accentText === colors.accent
66	        ? mixHex(colors.accent, colors.onAccent, 0.25)
67	        : colors.accentText,
68	      primaryInk: colors.onAccent,
69	      primaryText: colors.accentText,
70	      border: colors.border,
71	      borderStrong: colors.border,
72	      error: colors.danger,
73	      errorSurface: dangerSurface,
74	      warning: colors.warning,
75	      success: colors.success,
76	      info: colors.info,
77	      userBubble: mixHex(colors.surfaceMuted, colors.accent, name === "dark" ? 0.14 : 0.08),
78	      overlay: name === "dark" ? "rgba(0, 0, 0, 0.72)" : "rgba(28, 33, 27, 0.28)",
79	    },
80	    statusBarStyle: name === "dark" ? "light" : "dark",
81	  };
82	}

